import pandas as pd


def _is_different(a, b):
    """Compare two scalar values with legacy NULL semantics:
    NULL vs NULL -> not different; NULL vs non-NULL -> different;
    otherwise plain inequality."""
    a_na = pd.isna(a)
    b_na = pd.isna(b)
    if a_na and b_na:
        return False
    if a_na != b_na:
        return True
    return a != b


def run(inputs: dict) -> dict:
    dim_store = inputs["DIM_STORE"].copy()
    stg = inputs["STG_STORE_FULL"].copy()
    batch_control = inputs["BATCH_CONTROL"].copy()

    # Exactly one batch date.
    b = batch_control["batch_date"].iloc[0]

    # Distinct snapshot rows (exact duplicates collapse).
    stg_distinct = stg.drop_duplicates(subset=["store_id", "region", "format"])

    # Build lookup of snapshot attributes keyed by store_id.
    stg_dict = {}
    for row in stg_distinct.itertuples(index=False):
        stg_dict[row.store_id] = (row.region, row.format)

    # Ensure dim_store has the expected columns even if empty.
    cols = ["store_id", "region", "format", "eff_start_date", "eff_end_date", "is_current"]
    for c in cols:
        if c not in dim_store.columns:
            dim_store[c] = pd.NA

    # Split historical (non-current) rows - never touched.
    is_current_mask = dim_store["is_current"] == 1
    hist_rows = dim_store[~is_current_mask].copy()

    current_rows_df = dim_store[is_current_mask].copy()
    current_dict = {}
    for row in current_rows_df.itertuples(index=False):
        current_dict[row.store_id] = row

    updated_current_records = []
    new_records = []

    processed_current_ids = set()

    for store_id, (region, fmt) in stg_dict.items():
        if store_id in current_dict:
            c = current_dict[store_id]
            region_diff = _is_different(c.region, region)
            format_diff = _is_different(c.format, fmt)

            if region_diff or format_diff:
                # Close the old current row.
                updated_current_records.append({
                    "store_id": store_id,
                    "region": c.region,
                    "format": c.format,
                    "eff_start_date": c.eff_start_date,
                    "eff_end_date": b,
                    "is_current": 0,
                })
                # Insert the new current version.
                new_records.append({
                    "store_id": store_id,
                    "region": region,
                    "format": fmt,
                    "eff_start_date": b,
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                })
            else:
                # No-op: keep the current row exactly as-is.
                updated_current_records.append({
                    "store_id": store_id,
                    "region": c.region,
                    "format": c.format,
                    "eff_start_date": c.eff_start_date,
                    "eff_end_date": c.eff_end_date,
                    "is_current": c.is_current,
                })
            processed_current_ids.add(store_id)
        else:
            # Brand-new store or reactivated store: always a new version.
            new_records.append({
                "store_id": store_id,
                "region": region,
                "format": fmt,
                "eff_start_date": b,
                "eff_end_date": pd.NaT,
                "is_current": 1,
            })

    # Current rows whose store_id is not in the snapshot: close them (store closed).
    for store_id, c in current_dict.items():
        if store_id not in stg_dict:
            updated_current_records.append({
                "store_id": store_id,
                "region": c.region,
                "format": c.format,
                "eff_start_date": c.eff_start_date,
                "eff_end_date": b,
                "is_current": 0,
            })

    pieces = [hist_rows]

    if updated_current_records:
        pieces.append(pd.DataFrame(updated_current_records, columns=cols))

    if new_records:
        pieces.append(pd.DataFrame(new_records, columns=cols))

    if pieces:
        result = pd.concat(pieces, ignore_index=True, sort=False)
    else:
        result = pd.DataFrame(columns=cols)

    # Ensure column order and presence.
    result = result.reindex(columns=cols)

    return {"dim_store_out": result}
